package com.ngocdevv.nativecook.blocks.sheets.iconmorphsheet

import android.graphics.BitmapFactory
import android.graphics.Typeface
import android.graphics.fonts.Font
import android.graphics.fonts.FontFamily
import android.os.Build
import android.util.Base64
import java.io.ByteArrayInputStream
import java.nio.ByteBuffer
import java.util.zip.GZIPInputStream

/** Original assets embedded so this block stays copyable without Gradle resource wiring. */
internal object IconMorphAssets {
    private fun decode(chunks: Array<String>): ByteArray {
        val compressed = Base64.decode(chunks.joinToString(""), Base64.DEFAULT)
        return GZIPInputStream(ByteArrayInputStream(compressed)).use { it.readBytes() }
    }
    private fun font(chunks: Array<String>, bold: Boolean): Typeface {
        if (Build.VERSION.SDK_INT < 29) return Typeface.create("sans-serif", if (bold) Typeface.BOLD else Typeface.NORMAL)
        val bytes = decode(chunks)
        val buffer = ByteBuffer.allocateDirect(bytes.size).apply { put(bytes); flip() }
        val font = Font.Builder(buffer).build()
        return Typeface.CustomFallbackBuilder(FontFamily.Builder(font).build()).build()
    }
    val regular: Typeface by lazy { font(regularData(), false) }
    val bold: Typeface by lazy { font(boldData(), true) }
    val avatar by lazy { val bytes = decode(avatarData()); BitmapFactory.decodeByteArray(bytes, 0, bytes.size) }
    private fun regularData() = arrayOf(
        "",
        "",
        "",
        "",
